// src/lib/streaks.ts, written by an AI assistant
const dayOf = (ts: string) => new Date(ts).toISOString().slice(0, 10);

Linh lives in Ho Chi Minh City (UTC+07:00). The API returns two of her completions in UTC:

"2026-10-20T15:00:00Z"   (22:00 on 20 October, her time)
"2026-10-20T23:30:00Z"   (06:30 on 21 October, her time)

Statement: "dayOf() puts these two completions on two consecutive days, so the streak code counts 2 days for them."

// runs: the lengths of the runs of consecutive days, e.g. [3, 1, 5]
function longestStreak(runs: number[]): number {
  return Math.max(...runs);
}

// a new learner with no completions: runs is []
console.log(JSON.stringify({ longest: longestStreak([]) }));

Statement: "For a learner with no completions this prints {\"longest\":null}, because Math.max() with no arguments returns -Infinity and JSON.stringify writes -Infinity as null."
